function renderBatchJob(batch,{quiet=false}={}){state.batch=batch;const tasks=batch.tasks||[];if(!tasks[state.taskIndex]){const running=tasks.findIndex(task=>task.status==="running");state.taskIndex=running>=0?running:Math.max(0,tasks.findIndex(task=>task.job_id))}renderBatchQueue();renderPipeline(selectedTask());renderSidebarJob(sidebarJob());$("#jobMessage").textContent=batchTaskHeadline(batch);setJobDetail(batchDetailText(batch),{error:batchDetailIsError(batch)});$("#jobProgress").style.width=`${batch.progress||0}%`;$("#jobCount").textContent=`${batchFinishedTotal(batch)} / ${batchEffectiveTotal(batch)}`;const task=selectedTask();$("#pageTotal").textContent=(task&&task.total)||0;$("#pageNumber").textContent=task&&task.total?state.currentPage:0;$("#activityRing").style.animation=batch.status==="running"?"spin 1s linear infinite":"none";syncPauseButton(batch);updateStartState();if(!state.queue.length&&tasks.length)setQueue(tasks.map(item=>item.source));renderPreview();if(batch.status==="failed"&&!quiet)toast(batch.error||t("job.failed"),true)}
function selectTask(index){state.taskIndex=index;renderBatchQueue();renderPipeline(selectedTask());renderPreview()}
function removeQueueAt(index){if(!isBatch(state.batch)&&state.queue.length>index){state.queue.splice(index,1);writeQueueText();if(state.taskIndex>=state.queue.length)state.taskIndex=0;renderBatchQueue();updateStartState()}}
function batchQueueClick(event){const drop=event.target.closest("[data-drop-task]");if(drop){dropQueuedTask(Number(drop.dataset.dropTask));return}const remove=event.target.closest("[data-remove]");if(remove){removeQueueAt(Number(remove.dataset.remove));return}const row=event.target.closest(".batch-task[data-index]");if(row&&isBatch(state.batch))selectTask(Number(row.dataset.index))}
// Dropping a waiting folder is a backend edit of the submitted batch, so it goes through its own
// endpoint and re-renders from the returned view; the row keeps its place as "已取消" because the
// remaining folders keep their original indexes and the backend skips the dropped one.
async function dropQueuedTask(index){const batch=state.batch;if(!isBatch(batch))return;const tasks=batch.tasks||[];const task=tasks.find(item=>item.index===index);if(!task)return;const name=task.name||folderName(task.source||"");if(!window.confirm(t("batch.task.dropConfirm",{name})))return;const watching=selectedTask();try{const view=await api(`/api/batches/${batch.id}/tasks/${index}/cancel`,{method:"POST"});if(watching&&watching.index===index)state.taskIndex=-1;state.currentJob=view;renderJob(view);pollJob();toast(t("batch.task.dropped"))}catch(error){toast(error.message,true);showSetupError(error.message)}}
async function renderChildOptions(parent){const list=$("#folderChildrenList");list.innerHTML=`<div class="empty-list">${escapeHtml(t("batch.pickChildren.empty"))}</div>`;let data;try{data=await api(`/api/paths/children?path=${encodeURIComponent(parent)}`)}catch(error){list.innerHTML=`<div class="empty-list">${escapeHtml(error.message)}</div>`;return false}const folders=data.folders||[];list._folders=folders;list.innerHTML=folders.length?folders.map((folder,index)=>`<label class="child-option${folder.images?"":" disabled"}"><input type="checkbox" data-child="${index}"${folder.images?"":" disabled"}><b>${escapeHtml(folder.name)}</b><small>${escapeHtml(folder.images?t("batch.pickChildren.images",{count:folder.images}):t("batch.pickChildren.none"))}</small></label>`).join(""):`<div class="empty-list">${escapeHtml(t("batch.pickChildren.empty"))}</div>`;return true}
async function pickChildFolders(){try{const first=$("#sourcePath").value.split(/\r?\n/).map(trimPath).filter(Boolean)[0]||null;const result=await api("/api/dialog/folder",{method:"POST",body:JSON.stringify({initial:first})});if(!result.path)return;if(!await renderChildOptions(result.path))return;const dialog=$("#folderChildren");if(dialog.showModal)dialog.showModal()}catch(error){toast(error.message,true)}}
function confirmChildFolders(){const list=$("#folderChildrenList");const folders=list._folders||[];const picked=$$('#folderChildrenList input[type="checkbox"]:checked').map(box=>folders[Number(box.dataset.child)]).filter(Boolean).map(folder=>folder.path);$("#folderChildren").close();if(!picked.length)return;const added=addQueuePaths(picked);if(added.duplicates)toast(t("batch.duplicates",{count:added.duplicates}))}
async function cancelBatch(){const batch=state.currentJob;if(!isBatch(batch)||!isJobActive(batch))return;if(!window.confirm(t("batch.cancelConfirm")))return;(batch.tasks||[]).forEach(task=>{if(task.status==="queued")task.status="cancelled"});renderBatchQueue();state.pollTimer&&clearTimeout(state.pollTimer);try{renderJob(await api(`/api/jobs/${batch.id}/cancel`,{method:"POST"}))}catch(error){toast(error.message,true)}}
async function resumeBatch(){try{const data=await api("/api/batches");const batches=(data.batches||[]).filter(isBatch);if(!batches.length)return false;const active=batches.find(batch=>batch.status==="queued"||batch.status==="running");if(active){state.taskIndex=-1;restoreJobForm(active);renderJob(active);pollJob()}else await openJob(batches[0].id);return true}catch{return false}}
function updateStartState(){const reviewed=!!$("#reviewedTranscript")?.value.trim();const missing=!reviewed&&state.models.some(model=>isLocalModel(model)&&model.required&&!model.ready);const running=isJobActive(state.currentJob);const backend=$("#inferenceBackend")?.value||"ollama";const ocr=$("#ocrBackend")?.value||"hybrid";const missingName=!reviewed&&((backend==="ollama"&&!$("#ollamaModel")?.value.trim())||(backend==="online"&&!$("#onlineModel")?.value.trim())||(['hybrid','ollama'].includes(ocr)&&!$("#ollamaOcrModel")?.value.trim()));$("#startButton").disabled=!state.queue.length||missing||missingName||running;$("#startButton").title=missing?t("translation.start.missingModels"):missingName?t("translation.start.missingName"):""}
async function startJob(){applySourceText(true);if(!state.queue.length){showSetupError(t("batch.empty"));toast(t("batch.empty"),true);return}const root=trimPath($("#outputPath").value);const clash=root&&state.queue.find(path=>trimPath(path).toLowerCase()===root.toLowerCase());if(clash){showSetupError(t("batch.outputConflict",{path:clash}));return}clearSetupError();const payload={source:state.queue.slice(),output:root,...collectSettings(),reviewed_transcript:$("#reviewedTranscript").value.trim()||null};try{const job=await api("/api/batches",{method:"POST",body:JSON.stringify(payload)});state.currentJob=job;state.batch=isBatch(job)?job:null;state.taskIndex=-1;state.currentPage=1;renderJob(job);pollJob()}catch(error){showSetupError(error.message);toast(error.message,true)}}
async function resumeJob(){try{const data=await api("/api/jobs");const active=data.jobs.find(isJobActive);if(active){await openJob(active.id);pollJob();return}const latest=data.jobs.find(job=>job.status==="complete");if(latest){await openJob(latest.id);return}renderSidebarJob(data.jobs[0]||null)}catch{}}
function phaseIndex(job){if(job?.phase==="ocr")return job.total&&job.current/job.total>=.5?1:0;if(job?.phase==="translate")return 2;if(job?.phase==="render"||job?.phase==="complete")return 3;return 0}
const ACTIVE_STATUSES=["queued","running","paused"];
function isJobActive(job){return !!job&&ACTIVE_STATUSES.includes(job.status)}
function formatClock(value){if(!value)return"";const date=new Date(value);if(Number.isNaN(date.getTime()))return"";const pad=number=>String(number).padStart(2,"0");return`${pad(date.getHours())}:${pad(date.getMinutes())}`}
function formatDuration(seconds){const total=Math.max(0,Math.round(seconds));const hours=Math.floor(total/3600);const minutes=Math.floor(total%3600/60);const rest=total%60;const pad=number=>String(number).padStart(2,"0");return hours?`${hours}:${pad(minutes)}:${pad(rest)}`:`${minutes}:${pad(rest)}`}
function jobClock(job){if(!job||!job.started_at)return"";const start=new Date(job.started_at).getTime();if(Number.isNaN(start))return"";const paused=(job.paused_seconds||0)*1000+(job.paused_at?Date.now()-new Date(job.paused_at).getTime():0);const end=job.finished_at?new Date(job.finished_at).getTime():Date.now();const elapsed=Math.max(0,(end-start-paused)/1000);const progress=job.progress||0;const parts=[t("job.clock.start",{time:formatClock(job.started_at)})];if(job.finished_at){parts.push(t("job.clock.total",{time:formatDuration(elapsed)}))}else{parts.push(t("job.clock.elapsed",{time:formatDuration(elapsed)}));if(progress>=3)parts.push(t("job.clock.eta",{time:formatDuration(elapsed/progress*(100-progress))}))}return parts.join("\n")}
function sidebarJobText(job){if(!job)return{t:t("job.notStarted"),d:t("job.idle")};if(isBatch(job))return{t:batchDisplayMessage(job),d:t("batch.sidebarDetail",{completed:job.completed||0,total:batchEffectiveTotal(job),failed:job.failed||0})};const status=job.status;if(status==="cancelled")return{t:t("job.cancelled"),d:t("job.cancelledDetail")};if(status==="paused")return{t:t("job.paused"),d:t("job.pausedDetail",{current:job.current||0,total:job.total||0})};return{t:jobDisplayMessage(job),d:`${job.progress||0}% · ${job.current||0}/${job.total||0}`}}
function renderSidebarJob(job){const box=$("#jobStatus");if(!box)return;const state_=job?job.status:"idle";box.dataset.state=state_;const text=sidebarJobText(job);$("#jobStatusText").textContent=text.t;$("#jobStatusDetail").textContent=text.d;const clock=$("#jobClock");if(clock)clock.textContent=jobClock(job);box.title=job?.error||`${text.t} · ${text.d}`;$("#cancelJob").hidden=!isJobActive(job)}
function jobDisplayMessage(job){if(!job)return t("job.notStarted");if(isBatch(job))return batchDisplayMessage(job);if(job.status==="cancelled")return t("job.cancelled");if(job.status==="paused")return t("job.paused");if(job.status==="failed")return t("job.failed");if(job.status==="complete"||job.phase==="complete")return t("job.complete");if(job.status==="queued"||job.phase==="queued")return t("job.queued");if(job.phase==="prepare")return t("job.preparing");if(["ocr","translate","render"].includes(job.phase))return t(`job.${job.phase}`,{current:job.current||0,total:job.total||0});return t("job.preparing")}
function renderPipeline(job){const active=phaseIndex(job);$$('.pipeline-step').forEach((step,index)=>{step.classList.toggle("done",job?.status==="complete"||index<active);step.classList.toggle("active",(job?.status==="running"||job?.status==="paused")&&index===active)});$$('.step-line').forEach((line,index)=>line.classList.toggle("done",job?.status==="complete"||index<active));$("#pipelineEstimate").textContent=job?.status==="running"?`${job.progress}%`:job?.status==="paused"?t("job.paused"):job?.status==="complete"?t("pipeline.complete"):job?.status==="failed"?t("job.failed"):job?.status==="cancelled"?t("job.cancelled"):t("pipeline.waiting")}
function renderJob(job,{quiet=false}={}){state.currentJob=job;if(isBatch(job)){renderBatchJob(job,{quiet});return}state.batch=null;renderPipeline(job);renderSidebarJob(job);$("#jobMessage").textContent=jobDisplayMessage(job);setJobDetail(job.error||`${job.phase||"queued"} · ${t("job.local")}`,{error:!!job.error});$("#jobProgress").style.width=`${job.progress||0}%`;$("#jobCount").textContent=`${job.current||0} / ${job.total||0}`;$("#pageTotal").textContent=job.total||0;$("#pageNumber").textContent=job.total?state.currentPage:0;$("#activityRing").style.animation=job.status==="running"?"spin 1s linear infinite":"none";syncPauseButton(job);updateStartState();if(job.total)renderPreview();if(job.status==="failed"&&!quiet)toast(job.error||t("job.failed"),true)}
async function pollJob(){clearTimeout(state.pollTimer);if(!state.currentJob)return;try{const job=await api(`/api/jobs/${state.currentJob.id}`);renderJob(job);if(isBatch(job)){if(job.status==="completed"){announceJobEnd("complete");toast(t("job.complete"));await refreshJobs()}else if(job.status==="failed"){announceJobEnd("failure");await refreshJobs()}else if(job.status==="cancelled"){announceJobEnd("failure");toast(t("job.cancelled"));await refreshJobs()}else state.pollTimer=setTimeout(pollJob,1000);return}if(isJobActive(job))state.pollTimer=setTimeout(pollJob,1000);else if(job.status==="complete"){announceJobEnd("complete");toast(t("job.complete"));await refreshJobs()}else if(job.status==="failed"){announceJobEnd("failure");await refreshJobs()}else if(job.status==="cancelled"){toast(t("job.cancelled"));await refreshJobs()}}catch(error){toast(error.message,true)}}
async function quitApp(){if(!window.confirm(t("settings.quitConfirm")))return;const button=$("#quitApp");button.disabled=true;try{await api("/api/shutdown",{method:"POST"});document.body.innerHTML=`<div class="shutdown-screen"><h1>${t("settings.quit.done")}</h1><p>${t("settings.quit.doneDetail")}</p></div>`;window.close()}catch(error){toast(error.message,true);button.disabled=false}}
function syncPauseButton(job){const button=$("#pauseButton");if(!button)return;const paused=jobPaused(job);const live=isJobActive(job);button.disabled=!live;button.dataset.paused=paused?"true":"false";$("#pauseButtonIcon").textContent=paused?"▶":"Ⅱ";$("#pauseButtonLabel").textContent=paused?t("job.resume"):t("job.pause")}
async function togglePause(){const job=state.currentJob;if(!isJobActive(job))return;const paused=jobPaused(job);const button=$("#pauseButton");button.disabled=true;try{const next=await api(`/api/jobs/${job.id}/${paused?"resume":"pause"}`,{method:"POST"});renderJob(next);toast(paused?t("job.resumed"):t("job.pausedToast"));if(!paused)pollJob()}catch(error){toast(error.message,true)}finally{button.disabled=!isJobActive(state.currentJob)}}
async function cancelCurrentJob(){const job=state.currentJob;if(!isJobActive(job))return;if(isBatch(job)){await cancelBatch();return}if(!window.confirm(t("job.cancelConfirm")))return;const button=$("#cancelJob");button.disabled=true;try{renderJob(await api(`/api/jobs/${job.id}/cancel`,{method:"POST"}))}catch(error){toast(error.message,true)}finally{button.disabled=false}}
function setPreviewImage(image,url,key){if(image.dataset.previewKey===key)return;image.dataset.previewKey=key;image.hidden=false;image.src=`${url}?t=${Date.now()}`}
function outputPreviewReady(job,page){return job.status==="complete"||job.phase==="complete"||(job.phase==="render"&&Number(job.current)>=page)}
function pendingPreviewMessage(job){if(job.phase==="ocr")return t("preview.output.waitOcr");if(job.phase==="translate")return t("preview.output.waitTranslation");if(job.status==="failed")return t("preview.output.failed");return t("preview.output.waiting")}
function resetPreview(){const canvas=$("#previewCanvas");canvas.className="preview-canvas empty";["#sourcePreview","#outputPreview"].forEach(selector=>{const image=$(selector);image.hidden=true;image.removeAttribute("src");delete image.dataset.previewKey});$("#outputPending").hidden=false;$("#previewName").textContent=t("preview.none");$("#pageNumber").textContent=0;$("#pageTotal").textContent=0;$("#prevPage").disabled=true;$("#nextPage").disabled=true;$("#pageSlider").disabled=true;fillPageSlider(1,1);$("#pageSliderLabel").textContent=""}
function renderPreview(){const job=previewTarget();if(!job||!job.total){resetPreview();return}const canvas=$("#previewCanvas");canvas.className=`preview-canvas mode-${state.previewMode}`;canvas.classList.remove("empty");const source=$("#sourcePreview");const output=$("#outputPreview");const pending=$("#outputPending");const sourceKey=`${job.id}:source:${state.currentPage}`;setPreviewImage(source,`/api/jobs/${job.id}/preview/source/${state.currentPage}`,sourceKey);if(outputPreviewReady(job,state.currentPage)){pending.hidden=true;const outputKey=`${job.id}:output:${state.currentPage}`;setPreviewImage(output,`/api/jobs/${job.id}/preview/output/${state.currentPage}`,outputKey);output.onerror=()=>{output.hidden=true;pending.hidden=false;pending.textContent=t("preview.output.unavailable");output.removeAttribute("src");delete output.dataset.previewKey}}else{output.hidden=true;output.removeAttribute("src");delete output.dataset.previewKey;pending.hidden=false;pending.textContent=pendingPreviewMessage(job)}$("#previewName").textContent=t("preview.page",{page:state.currentPage});$("#pageNumber").textContent=state.currentPage;$("#prevPage").disabled=state.currentPage<=1;$("#nextPage").disabled=state.currentPage>=job.total;syncPageSlider(job)}
function localizedStatus(status){return t(`status.${status==="completed"?"complete":status}`)}
async function refreshJobs(){const button=$("#refreshJobs");if(button)button.disabled=true;try{const data=await api("/api/jobs");const list=$("#jobList");list.innerHTML=data.jobs.length?data.jobs.map(job=>`<button class="panel utility-item job-item" data-job-id="${job.id}"><div><b>${escapeHtml(jobSourceLabel(job))}</b><small>${escapeHtml(jobDisplayMessage(job))} · ${job.progress}% · ${escapeHtml(formatJobTime(job.updated_at))}</small></div><span class="status-chip ${job.status==="complete"||job.status==="completed"?"ready":job.status==="failed"?"error":job.status==="paused"?"paused":""}">${escapeHtml(localizedStatus(job.status))}</span></button>`).join(""):`<div class="panel empty-list">${escapeHtml(t("history.empty"))}</div>`;$$('.job-item').forEach(item=>item.addEventListener("click",()=>openJob(item.dataset.jobId)));return data.jobs.length}catch(error){toast(error.message,true);return null}finally{if(button)button.disabled=false}}
function formatJobTime(value){if(!value)return"";const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value);const pad=number=>String(number).padStart(2,"0");return`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`}
async function refreshJobsFeedback(){const count=await refreshJobs();if(count===null)return;toast(t("history.refreshed",{count}))}
// A refresh must bring the whole form back, not just the queue rows: a batch record carries
// the sources plus the output ROOT the user typed, so a mid-run F5 has to repopulate the form
// too, otherwise the next submitted batch silently writes beside each source folder.
function restoreJobForm(job){if(!job)return;if(!job.request)job.request={};if(Array.isArray(job.request.source))job.request.source=job.request.source.join("\n");if(job.request.source===undefined)job.request.source=(job.tasks||[]).map(task=>task.source).join("\n");if(job.request.source===undefined)job.request.source="";if(job.request.output===undefined||job.request.output===null)job.request.output="";$("#sourcePath").value=job.request.source;$("#outputPath").value=job.request.output;const reviewed=$("#reviewedTranscript");if(reviewed)reviewed.value=job.request.reviewed_transcript||"";state.queue=parseQueueText(job.request.source);writeQueueText();clearSetupError();renderBatchQueue()}
async function openJob(jobId){try{const job=await api(`/api/jobs/${jobId}`);state.taskIndex=-1;restoreJobForm(job);state.currentPage=1;renderJob(job,{quiet:true});updateStartState();switchView("workspace")}catch(error){toast(error.message,true)}}
function switchView(view,{refresh=true}={}){state.activeView=view;$$('.nav-item').forEach(button=>button.classList.toggle("active",button.dataset.view===view));$$('.view').forEach(panel=>panel.classList.toggle("active",panel.dataset.viewPanel===view));const labels={workspace:"app.title",history:"history.title",models:"modelPage.title",settings:"settings.title"};$("#pageTitle").textContent=t(labels[view]||labels.workspace);if(refresh&&view==="history")refreshJobs();if(refresh&&view==="models")refreshModels()}
function refreshLocalizedUI(){$("#uiLanguage").value=window.MLS_I18N.getLocale();switchView(state.activeView,{refresh:false});updateBackendUI();renderModels();renderSidebarJob(sidebarJob());if(state.currentJob){renderJob(state.currentJob);syncPauseButton(state.currentJob)}else{$("#jobMessage").textContent=t("job.notStarted");setJobDetail(t("job.selectFolders"));renderBatchQueue();updateStartState()}if(state.systemHome)$("#appHome").textContent=t("settings.home",{path:state.systemHome});renderCpuChoices(state.cpu,state.settings&&state.settings.cpu_threads);refreshJobs()}
function fillPageSlider(page,total){const slider=$("#pageSlider");const pct=total>1?((page-1)/(total-1))*100:0;slider.style.setProperty("--fill",`${pct}%`);slider.style.setProperty("--tick",`${total>1?100/(total-1):100}%`);slider.value=page}
function syncPageSlider(job){const slider=$("#pageSlider");const total=job?.total||0;slider.disabled=total<2;slider.min=1;slider.max=Math.max(1,total);const page=total?Math.min(total,Math.max(1,state.currentPage)):1;fillPageSlider(page,Math.max(1,total));$("#pageSliderLabel").textContent=total?`${page} / ${total}`:""}
